// CSI (any final byte), OSC terminated by BEL or ST, and two character ESC
// sequences. paint() emits only SGR, but stripAnsi also guards the width
// accounting against sequences that arrived from outside the render model,
// because sanitizeText removes those at the entry point and this is the second
// line of defence.
const ANSI_PATTERN =
  /\u001b(?:\[[0-?]*[ -/]*[@-~]|\][^\u0007]*(?:\u0007|\u001b\\)|[@-Z\\-_])/g;

// Every character that a terminal interprets rather than prints: C0 controls
// including newline, DEL, C1, zero width and bidi override characters. A hold
// modal renders strings that came from an agent and an upstream server, and an
// escape sequence injected there can clear the screen, move the cursor or spoof
// a colour coded allow verdict in the seconds before a human approves a write.
// The replacement is a visible question mark, not a deletion, so a hostile or
// merely broken tool id still shows that something odd was in the data.
const UNPRINTABLE =
  /[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060-\u2069\ufeff]/g;

function sanitizeText(value        )         {
  return value.replace(UNPRINTABLE, "?");
}

function stripAnsi(value        )         {
  return value.replace(ANSI_PATTERN, "");
}

/**
 * Cell width per code point, not per code unit. East Asian wide and fullwidth
 * characters occupy two terminal cells, combining marks occupy none, and
 * treating either wrongly either wraps a line or misaligns a box. This is the
 * pragmatic range table, not the full Unicode width table: the package has a
 * no dependency rule, and the uncovered ranges are scripts this product is
 * unlikely to render in a tool id. The adversarial test covers CJK and emoji.
 */
function cellWidth(point        )         {
  const code = point.codePointAt(0) ?? 0;
  if (
    (code >= 0x0300 && code <= 0x036f) ||
    (code >= 0x1ab0 && code <= 0x1aff) ||
    (code >= 0x1dc0 && code <= 0x1dff) ||
    (code >= 0x20d0 && code <= 0x20ff) ||
    (code >= 0xfe00 && code <= 0xfe0f)
  )
    return 0;
  if (
    (code >= 0x1100 && code <= 0x115f) ||
    (code >= 0x2e80 && code <= 0xa4cf) ||
    (code >= 0xa960 && code <= 0xa97f) ||
    (code >= 0xac00 && code <= 0xd7a3) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xfe10 && code <= 0xfe19) ||
    (code >= 0xfe30 && code <= 0xfe6f) ||
    (code >= 0xff00 && code <= 0xff60) ||
    (code >= 0xffe0 && code <= 0xffe6) ||
    (code >= 0x1f300 && code <= 0x1f64f) ||
    (code >= 0x1f680 && code <= 0x1f8ff) ||
    (code >= 0x1f900 && code <= 0x1f9ff) ||
    (code >= 0x1fa70 && code <= 0x1faff) ||
    (code >= 0x20000 && code <= 0x3fffd)
  )
    return 2;
  // Emoji and symbol blocks that terminals draw two cells wide although the
  // East Asian Width property alone does not force it: the presentation
  // selector defaults to emoji style and every mainstream terminal uses the
  // emoji width. Missing these made the model undercount real terminal rows
  // while agreeing with itself, which is the worst failure shape for a
  // border drawing renderer.
  if (
    (code >= 0x2600 && code <= 0x27bf) ||
    (code >= 0x1f000 && code <= 0x1f2ff) ||
    (code >= 0x1f0a0 && code <= 0x1f0f5)
  )
    return 2;
  return 1;
}

function visibleLength(value        )         {
  let total = 0;
  for (const point of stripAnsi(value)) total += cellWidth(point);
  return total;
}

function fit(
  value        ,
  width        ,
  side                   = "right",
)         {
  if (width <= 0) return "";
  const plain = stripAnsi(value);
  if (visibleLength(plain) <= width) return value;
  if (width === 1) return ".";
  const points = [...plain];
  if (side === "left") {
    let kept = "";
    let used = 0;
    for (let index = points.length - 1; index >= 0; index -= 1) {
      const point = points[index] ;
      const cells = cellWidth(point);
      // Reserve one cell for the truncation marker and never split a wide
      // character: a half wide character renders as replacement garbage.
      if (used + cells > width - 1) break;
      kept = point + kept;
      used += cells;
    }
    return `.${kept}`;
  }
  let kept = "";
  let used = 0;
  for (const point of points) {
    const cells = cellWidth(point);
    if (used + cells > width - 1) break;
    kept += point;
    used += cells;
  }
  return `${kept}.`;
}

function pad(value        , width        )         {
  const fitted = fit(value, width);
  return `${fitted}${" ".repeat(Math.max(0, width - visibleLength(fitted)))}`;
}

function rule(width        , character = "-")         {
  const cells = Number.isFinite(width) ? Math.max(0, Math.floor(width)) : 0;
  const glyph = sanitizeText(character);
  const glyphWidth = visibleLength(glyph);
  if (glyphWidth <= 0) return " ".repeat(cells);
  const repeats = Math.floor(cells / glyphWidth);
  return glyph.repeat(repeats) + " ".repeat(cells - repeats * glyphWidth);
}

function crop(
  lines                   ,
  width        ,
  height        ,
)           {
  return lines.slice(0, Math.max(0, height)).map((line) => fit(line, width));
}

                                                      

function myersOps(a                   , b                   )           {
  const n = a.length,
    m = b.length;
  if (!n && !m) return [];
  if (!n) return b.map((line) => ({ kind: "+"         , line }));
  if (!m) return a.map((line) => ({ kind: "-"         , line }));
  if (n * m > 4000000)
    return [
      ...a.map((line) => ({ kind: "-"         , line })),
      ...b.map((line) => ({ kind: "+"         , line })),
    ];
  const max = n + m,
    offset = max,
    trace               = [];
  const v = new Int32Array(2 * max + 1).fill(-1);
  v[offset + 1] = 0;
  let done = false;
  for (let d = 0; d <= max && !done; d++) {
    for (let k = -d; k <= d; k += 2) {
      const index = offset + k;
      let x        ;
      if (k === -d || (k !== d && v[index - 1]  < v[index + 1] ))
        x = v[index + 1] ;
      else x = v[index - 1]  + 1;
      let y = x - k;
      while (x < n && y < m && a[x] === b[y]) {
        x++;
        y++;
      }
      v[index] = x;
      if (x >= n && y >= m) {
        done = true;
        break;
      }
    }
    trace.push(Int32Array.from(v));
  }
  const ops           = [];
  let x = n,
    y = m;
  for (let d = trace.length - 1; d > 0; d--) {
    const prev = trace[d - 1] ,
      k = x - y;
    const down =
      k === -d || (k !== d && prev[offset + k - 1]  < prev[offset + k + 1] );
    const prevK = down ? k + 1 : k - 1;
    const prevX = prev[offset + prevK] ,
      prevY = prevX - prevK;
    while (x > prevX && y > prevY) {
      x--;
      y--;
      ops.push({ kind: " ", line: a[x]  });
    }
    if (down) {
      y--;
      ops.push({ kind: "+", line: b[y]  });
    } else {
      x--;
      ops.push({ kind: "-", line: a[x]  });
    }
  }
  while (x > 0 && y > 0) {
    x--;
    y--;
    ops.push({ kind: " ", line: a[x]  });
  }
  while (x > 0) {
    x--;
    ops.push({ kind: "-", line: a[x]  });
  }
  while (y > 0) {
    y--;
    ops.push({ kind: "+", line: b[y]  });
  }
  return ops.reverse();
}

/** Line diff for review screens. Display only; the ledger stays authoritative. */
function unifiedDiff(
  before        ,
  after        ,
  context = 3,
  maxRows = 200,
)           {
  const ops = myersOps(before.split("\n"), after.split("\n"));
  if (ops.every((op) => op.kind === " ")) return ["No changes."];
  const rows           = [];
  let aLine = 1,
    bLine = 1,
    index = 0;
  while (index < ops.length) {
    while (index < ops.length && ops[index] .kind === " ") {
      aLine++;
      bLine++;
      index++;
    }
    if (index >= ops.length) break;
    const hunkStart = Math.max(0, index - context);
    const lead = index - hunkStart;
    let end = index;
    while (end < ops.length) {
      if (ops[end] .kind !== " ") {
        end++;
        continue;
      }
      let run = 0;
      while (end + run < ops.length && ops[end + run] .kind === " ") run++;
      if (run > 2 * context || end + run >= ops.length) break;
      end += run;
    }
    const tail = Math.min(context, ops.length - end);
    const slice = ops.slice(hunkStart, end + tail);
    let aStart = aLine,
      bStart = bLine;
    for (const op of slice.slice(0, lead)) {
      if (op.kind !== "+") aStart--;
      if (op.kind !== "-") bStart--;
    }
    const aLen = slice.filter((op) => op.kind !== "+").length;
    const bLen = slice.filter((op) => op.kind !== "-").length;
    rows.push(
      "@@ -" + aStart + "," + aLen + " +" + bStart + "," + bLen + " @@",
    );
    for (const op of slice) rows.push(op.kind + op.line);
    for (const op of slice) {
      if (op.kind !== "+") aLine++;
      if (op.kind !== "-") bLine++;
    }
    index = end + tail;
  }
  if (rows.length <= maxRows) return rows;
  return [
    ...rows.slice(0, maxRows),
    "... (" + (rows.length - maxRows) + " more lines)",
  ];
}

/** Split unified diff rows into per hunk chunks, each starting with its @@
 * header. Lines before the first header are display text (for example
 * "No changes."), not diff scope, so they form no hunk. */
function splitDiffHunks(rows                   )             {
  const chunks             = [];
  for (const row of rows) {
    if (row.startsWith("@@")) chunks.push([row]);
    else if (chunks.length) chunks[chunks.length - 1] .push(row);
  }
  return chunks;
}

/** Mark each hunk header with its selection state. Deselected hunks keep
 * their body visible but flagged, so review never hides scope silently. */
function renderHunkSelection(
  chunks                                ,
  selected                    ,
)           {
  const out           = [];
  chunks.forEach((chunk, index) => {
    const mark = selected[index] !== false ? "[x]" : "[ ]";
    chunk.forEach((row, rowIndex) => {
      out.push(rowIndex === 0 ? `${mark} ${index + 1}. ${row}` : `    ${row}`);
    });
  });
  return out;
}


