const NOMO_PALETTE = COLOR_THEMES.default;

(() => {
  const map                       = {}                        ;
  for (const tone of Object.keys(NOMO_PALETTE)          ) {
    map[tone] = ansi16(NOMO_PALETTE[tone]);
  }
  return map;
})();

(() => {
  const map                       = {}                        ;
  for (const tone of Object.keys(NOMO_PALETTE)          ) {
    map[tone] = ansi256(NOMO_PALETTE[tone]);
  }
  return map;
})();

function paint(
  text        ,
  tone      ,
  capabilities                      ,
  bold = false,
)         {
  return paintWithPalette(text, tone, NOMO_PALETTE, capabilities, bold);
}

function getThemeConfig(env                              )              {
  return resolveThemeConfig(env);
}

function getSymbols(preset               )            {
  return getSymbolSet(preset ?? "unicode");
}

function getPalette(theme             )               {
  return getColorPalette(theme ?? "default");
}

function paintUserMessage(
  text        ,
  palette              ,
  capabilities                      ,
)         {
  return paintUserMessageWithPalette(text, palette, capabilities);
}


