//# sourceURL=packages/workbench/src/provider-adapters/types.ts

const GOOGLE_PROJECT_ID = /^(?:[a-z][a-z0-9-]{4,28}[a-z0-9]|[0-9]{6,20})$/;
const LOCATION_ID = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

function standardVertexBaseUrl(location        )                     {
  if (location === "global") return "https://aiplatform.googleapis.com";
  if (!LOCATION_ID.test(location)) return undefined;
  return `https://${location}-aiplatform.googleapis.com`;
}

function isStandardVertexOptions(value         )                                 {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const options = value                           ;
  return (
    Object.keys(options).length === 3 &&
    Object.hasOwn(options, "mode") &&
    Object.hasOwn(options, "projectId") &&
    Object.hasOwn(options, "location") &&
    options.mode === "standard" &&
    typeof options.projectId === "string" &&
    GOOGLE_PROJECT_ID.test(options.projectId) &&
    typeof options.location === "string" &&
    standardVertexBaseUrl(options.location) !== undefined
  );
}


//# sourceURL=packages/workbench/src/provider-adapters/google-vertex-config.ts

function isBedrockMantleBaseUrl(value        )          {
  try {
    const endpoint = new URL(value);
    return (
      endpoint.protocol === "https:" &&
      /^bedrock-mantle\.[a-z]{2}(?:-[a-z0-9]+)+-\d+\.api\.aws$/i.test(endpoint.hostname) &&
      !endpoint.username &&
      !endpoint.password &&
      !endpoint.port &&
      !endpoint.search &&
      !endpoint.hash &&
      ["/openai/v1", "/openai/v1/"].includes(endpoint.pathname)
    );
  } catch {
    return false;
  }
}


//# sourceURL=packages/workbench/src/provider-adapters/bedrock-mantle-config.ts

function cloudflareAiGatewayRouteForTransport(
  transport        ,
)                                           {
  if (transport === "anthropic-messages") return "anthropic";
  if (transport === "openai-completions") return "compat";
  if (transport === "openai-responses") return "openai";
  return null;
}

function normalizeCloudflareAiGatewayEndpoint(
  url     ,
  transport        ,
)                {
  if (
    url.protocol !== "https:" ||
    url.hostname !== "gateway.ai.cloudflare.com" ||
    url.username ||
    url.password ||
    url.port ||
    url.search ||
    url.hash
  ) return null;

  const path = url.pathname.replace(/\/$/, "");
  const match = /^\/v1\/([^/]+)\/([^/]+)\/(anthropic|compat|openai)(?:\/v1)?$/.exec(path);
  if (!match) return null;

  try {
    const accountId = decodeURIComponent(match[1]);
    const gatewayId = decodeURIComponent(match[2]);
    const forbidden = /[<>/\\\u0000-\u001f\u007f]/;
    if (
      !accountId ||
      !gatewayId ||
      accountId === "." ||
      accountId === ".." ||
      gatewayId === "." ||
      gatewayId === ".." ||
      forbidden.test(accountId) ||
      forbidden.test(gatewayId)
    ) return null;
  } catch {
    return null;
  }

  const route = match[3];
  const expected = cloudflareAiGatewayRouteForTransport(transport);
  if (!expected || route !== expected || (route !== "anthropic" && path.endsWith("/v1")))
    return null;

  return `https://gateway.ai.cloudflare.com${path}${route === "anthropic" && !path.endsWith("/v1") ? "/v1" : ""}`;
}


//# sourceURL=packages/workbench/src/provider-adapters/cloudflare-ai-gateway-config.ts

const WORKERS_AI_ENDPOINT =
  /^\/client\/v4\/accounts\/([A-Za-z0-9_-]{1,128})\/ai\/v1\/?$/;

function normalizeCloudflareWorkersAiEndpoint(input     )                {
  if (
    input.protocol !== "https:" ||
    input.hostname !== "api.cloudflare.com" ||
    input.username ||
    input.password ||
    input.port ||
    input.search ||
    input.hash
  ) return null;
  const match = WORKERS_AI_ENDPOINT.exec(input.pathname);
  if (!match) return null;
  // Source: https://developers.cloudflare.com/workers-ai/configuration/open-ai-compatibility/
  return `https://api.cloudflare.com/client/v4/accounts/${match[1]}/ai/v1`;
}


