function page   (
  source              ,
  query                 ,
  scope = "workspace",
) {
  const filter = [...query.entries()]
    .filter(([key]) => !["cursor", "limit"].includes(key))
    .sort()
    .toString();
  const signature = createHash("sha256")
    .update(filter)
    .digest("hex")
    .slice(0, 16);
  const identity = (row   ) => {
    const item = row                           ;
    return String(item.id ?? item.holdId ?? item.seq ?? JSON.stringify(row));
  };
  let offset = 0;
  if (query.get("cursor")) {
    const cursor = JSON.parse(
      Buffer.from(query.get("cursor") , "base64url").toString(),
    );
    if (cursor.filter !== signature || typeof cursor.last !== "string")
      throw new Error("Invalid cursor for this filter.");
    offset = source.findIndex((row) => identity(row) === cursor.last) + 1;
    if (!offset)
      throw new Error(
        "Cursor anchor is no longer available. Refresh the list.",
      );
  }
  const limit = Math.min(100, Math.max(1, Number(query.get("limit")) || 50));
  const items = source.slice(offset, offset + limit),
    hasMore = offset + limit < source.length;
  return {
    items,
    nextCursor: hasMore
      ? Buffer.from(
          JSON.stringify({ last: identity(items.at(-1) ), filter: signature }),
        ).toString("base64url")
      : null,
    hasMore,
    total: source.length,
    asOf: new Date().toISOString(),
    scope,
  };
}
function sessionPatch(body                         ) {
  const patch   
                   
                     
                       
                     
                    
    = {};
  for (const key of ["title", "project"]         )
    if (key in body) {
      if (
        typeof body[key] !== "string" ||
        body[key].length > 160 ||
        !body[key].trim()
      )
        throw new Error(`Invalid ${key}.`);
      patch[key] = body[key].trim();
    }
  for (const key of ["pinned", "archived"]         )
    if (key in body) {
      if (typeof body[key] !== "boolean") throw new Error(`Invalid ${key}.`);
      patch[key] = body[key];
    }
  if ("tags" in body) {
    if (
      !Array.isArray(body.tags) ||
      body.tags.length > 20 ||
      !body.tags.every((tag) => typeof tag === "string" && tag.length <= 40)
    )
      throw new Error("Invalid tags.");
    patch.tags = body.tags            ;
  }
  return patch;
}
function preferencePatch(body                         ) {
  if (
    "permissionMode" in body ||
    (typeof body.preferences === "object" &&
      body.preferences !== null &&
      "permissionMode" in body.preferences)
  )
    throw new Error("Permission mode is server-controlled.");
  const result                         = {};
  const enums                           = {
    defaultAgent: ["cloud", "prime-agent"],
    defaultAgentPreset: ["default", "planner", "reviewer", "implementer"],
    locale: ["cs", "en"],
    appearance: ["system", "light", "dark"],
    sendBehavior: ["enter", "mod-enter"],
  };
  for (const key of [
    "defaultAgent",
    "defaultAgentPreset",
    "defaultProvider",
    "defaultModel",
    "locale",
    "appearance",
    "sendBehavior",
  ])
    if (key in body) {
      const value = body[key];
      if (
        typeof value !== "string" ||
        !value.length ||
        value.length > 200 ||
        (enums[key] && !enums[key].includes(value))
      )
        throw new Error(`Invalid ${key}.`);
      result[key] = value;
    }
  return result;
}
function documentView(
  state                ,
  path        ,
  sessionId        ,
) {
  const content = Object.hasOwn(state.files, path) ? state.files[path]  : null;
  const last = [...state.operations].reverse().find((op) => op.path === path);
  return {
    path,
    content,
    revision: last?.id ?? null,
    bytes: content === null ? 0 : Buffer.byteLength(content),
    updatedAt: last?.at ?? null,
    sessionId,
  };
}
function filterRows   (rows              , query                 )      {
  const q = (query.get("q") ?? "").toLowerCase();
  const result = rows.filter((row) => {
    const r = row                           ;
    return (
      (!q || JSON.stringify(row).toLowerCase().includes(q)) &&
      [
        "status",
        "state",
        "model",
        "workspace",
        "sessionId",
        "tool",
        "klass",
        "decision",
      ].every((key) => !query.get(key) || r[key] === query.get(key)) &&
      (!query.get("outcome") ||
        String(r.decision ?? "").replace(/^execute:/, "") ===
          query.get("outcome")) &&
      (!query.get("from") ||
        String(r.at ?? r.createdAt ?? "") >= query.get("from") ) &&
      (!query.get("to") ||
        String(r.at ?? r.createdAt ?? "") <= query.get("to") )
    );
  });
  const sort = query.get("sort"),
    direction = query.get("order") === "asc" ? 1 : -1;
  if (sort && /^[A-Za-z][A-Za-z0-9]*$/.test(sort))
    result.sort((a, b) => {
      const x = (a                           )[sort],
        y = (b                           )[sort];
      return (
        direction *
        (typeof x === "number" && typeof y === "number"
          ? x - y
          : String(x ?? "").localeCompare(String(y ?? "")))
      );
    });
  return result;
}
                                                             


/** The two permission defaults are deliberately different and both are
 * explicit, because an embedder must never have to guess which one it got.
 *
 * `DEFAULT_LOCAL_PERMISSION_MODE` applies to a local operator surface (CLI,
 * TUI, the embedded Workbench) that is already gated by host user
 * authentication: the operator starts it deliberately, so an absent variable
 * means "not restricted".
 *
 * `DEFAULT_HTTP_PERMISSION_MODE` applies to the remote-facing control-plane
 * API, where an absent variable means "locked" and a human has to open it
 * explicitly.
 */
const DEFAULT_LOCAL_PERMISSION_MODE                 = "normal";

/** The only permission source accepted by the local server. Missing or
 * malformed configuration is intentionally read-only, never normal. */
function serverPermissionMode(value         )                 {
  return value === "plan" || value === "read-only" || value === "normal"
    ? value
    : "read-only";
}
                            
                                                              
                      
          
              
          
               
               
            
           
             
                      
          
             
                       
              
             
            
             
             
// A run status is a workspace-wide primitive, so the mapping from the older
